/**
 * Battleship Module Solver for Keep Talking and Nobody Explains
 *
 * Paste the manual text (the "Enemy fleet" list), then mark each shot as hit or miss on the 6×6
 * board. It counts every way the ships could still lie and names the cell most likely to hold
 * one — the fewest shots, at 20 s a shot.
 */
(function () {
  'use strict';

  // ── Solving: bomb_boomed's (window.BombLogic.battleship, bomb-logic.js) ──
  // Generated by bomb_boomed's scripts/build-conso-logic.mjs: re-run it to sync, don't copy code here.
  const { analyzeBattleship, parseBattleshipText, cellName, colLetter, parseCell, SAMPLE_MANUAL } = window.BombLogic.battleship;
  const K = window.ModuleKit;
  const { $, esc } = K;

  const WAIT = 20; // seconds between shots
  const COLS = 6, ROWS = 6; // the bomb's 6×6 module grid (A–F × 1–6)
  const STATUS_NEXT = { afloat: 'sunk', sunk: null, null: 'afloat' };
  const pct = p => (p >= 0.995 ? '100' : p < 0.005 ? '0' : String(Math.round(p * 100)));

  const state = {
    fleet: [], // [{ len, status }]
    fleetHits: 0, // hits marked when the fleet list was last pasted
    shots: [], // [{ i, result }] in the order fired
    lastShotAt: 0,
    res: null
  };
  window.battleshipModuleState = state;
  let waitTimer = null;

  function injectStyles() {
    K.injectBase();
    if ($('battleshipStyles')) return;
    const style = document.createElement('style');
    style.id = 'battleshipStyles';
    style.textContent = `
    .bs-fleet { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; margin-bottom: 10px; }
    .bs-ship { display: inline-flex; align-items: stretch; border: 1px solid #2d3366; border-radius: 999px; overflow: hidden; }
    .bs-ship button { border: 0; background: transparent; color: #e2e8f0; font: 12px 'JetBrains Mono', ui-monospace, monospace; padding: 4px 9px; cursor: pointer; }
    .bs-ship.afloat { border-color: #3b82f6; }
    .bs-ship.sunk { border-color: #ef4444; }
    .bs-ship.sunk button:first-child { text-decoration: line-through; color: #8892b0; }
    .bs-ship .mk-x { border-left: 1px solid #2d3366; padding: 4px 8px; }
    .bs-report { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin-bottom: 12px; font-size: 13px; }
    .bs-report .mk-btn.hit { border-color: #ef4444; color: #ff8a8a; }
    .bs-report .mk-btn.miss { border-color: #3b82f6; color: #8fb8ff; }
    .bs-wait { color: #4ade80; }
    .bs-wait.busy { color: #ffd875; font-weight: 700; }
    .bs-board { display: grid; grid-template-columns: 22px repeat(6, minmax(0, 1fr)); gap: 4px; max-width: 420px; margin-bottom: 12px; }
    .bs-lbl { display: flex; align-items: center; justify-content: center; font: 700 12px 'JetBrains Mono', ui-monospace, monospace; color: #8892b0; }
    .bs-cell { aspect-ratio: 1; border: 1px solid #2a2f5c; border-radius: 7px; background: #0b0d1d; color: #e2e8f0; font: 12px 'JetBrains Mono', ui-monospace, monospace; cursor: pointer; padding: 0; }
    .bs-cell:hover { border-color: #ffd875; }
    .bs-cell.empty { color: #5b6488; }
    .bs-cell.miss { background: #12152e; color: #8892b0; font-size: 18px; }
    .bs-cell.hit { background: #c0392b; border-color: #c0392b; color: #fff; font-size: 16px; font-weight: 700; }
    .bs-cell.target { outline: 3px solid #4ade80; outline-offset: 1px; font-size: 16px; }
    .bs-cell.tie { outline: 2px dashed #4ade80; }
    .bs-cell.sure { font-weight: 700; }
    `;
    document.head.appendChild(style);
  }

  function renderUI() {
    const section = $('battleshipSection');
    if (!section) return;
    section.innerHTML = `
      <div class="mk-shell">
        <div class="mk-head">
          <div class="mk-title"><span>🚢</span> Battleship Solver <span class="mk-pill">6×6 · 20 s a shot</span></div>
          <div class="mk-actions">
            <button class="mk-btn" type="button" data-act="undo">↶ Undo shot</button>
            <button class="mk-btn" type="button" data-act="newboard">New board</button>
            <button class="mk-btn" type="button" data-act="clear">Reset</button>
            <button class="mk-btn gold" type="button" data-act="sample">⚡ Sample</button>
          </div>
        </div>
        <div class="mk-layout">
          <div>
            <div class="mk-card">
              <div class="mk-card-title">Manual Text</div>
              <label class="mk-label" for="battleshipText">The "Enemy fleet" list — paste it again when a ship sinks</label>
              <textarea id="battleshipText" class="mk-textarea" spellcheck="false" placeholder="Enemy fleet:&#10;• 3-cell ship, afloat&#10;• 2-cell ship, afloat"></textarea>
              <div class="mk-label" style="margin-bottom:6px;">Fleet</div>
              <div id="battleshipFleet" class="bs-fleet"></div>
              <div id="battleshipFleetNote"></div>
            </div>
            <details class="mk-details">
              <summary>How it picks the cell</summary>
              <div id="battleshipWork" style="font-size:12px; line-height:1.6; color:#cbd5e1;"></div>
            </details>
          </div>
          <div>
            <div class="mk-banner">
              <div class="mk-banner-row">
                <div>
                  <div class="mk-banner-lbl">Fire At</div>
                  <div id="battleshipAnswer" class="mk-answer"></div>
                  <div id="battleshipStats" class="mk-stats"></div>
                </div>
                <button id="battleshipCopyBtn" class="mk-btn gold" type="button" data-act="copy">📋 Copy</button>
              </div>
            </div>
            <div id="battleshipReport"></div>
            <div id="battleshipTies"></div>
            <div id="battleshipBoard"></div>
            <div id="battleshipNote"></div>
          </div>
        </div>
      </div>`;
    $('battleshipText').addEventListener('input', (e) => handleText(e.target.value));
    section.addEventListener('click', onClick);
    section.addEventListener('change', onChange);
    update();
  }

  const shotMap = () => Object.fromEntries(state.shots.map(s => [s.i, s.result]));
  const hitCount = () => state.shots.filter(s => s.result === 'hit').length;

  function handleText(t) {
    const p = parseBattleshipText(t);
    if (p.ships.length) { state.fleet = p.ships; state.fleetHits = hitCount(); }
    for (const s of p.shots) {
      const i = parseCell(s.cell, COLS, ROWS);
      if (i < 0) continue;
      const at = state.shots.findIndex(x => x.i === i);
      if (at >= 0) state.shots[at] = { i, result: s.result }; else state.shots.push({ i, result: s.result });
    }
    update();
  }

  function mark(i, result) {
    const had = shotMap()[i];
    const at = state.shots.findIndex(s => s.i === i);
    if (!result) state.shots = state.shots.filter(s => s.i !== i);
    else if (at >= 0) state.shots = state.shots.map(s => (s.i === i ? { i, result } : s));
    else state.shots = [...state.shots, { i, result }];
    if (result && !had) startWait();
    update();
  }

  // the 20-second wait after a shot
  function startWait() {
    state.lastShotAt = Date.now();
    clearInterval(waitTimer);
    waitTimer = setInterval(() => {
      showWait();
      if (Date.now() - state.lastShotAt > (WAIT + 1) * 1000) clearInterval(waitTimer);
    }, 250);
  }
  function showWait() {
    const el = $('battleshipWait');
    if (!el) return;
    const left = state.lastShotAt ? Math.max(0, WAIT - Math.floor((Date.now() - state.lastShotAt) / 1000)) : 0;
    el.className = `bs-wait ${left ? 'busy' : ''}`;
    el.textContent = left ? `⏳ wait ${left}s before the next shot` : state.lastShotAt ? '✓ the defuser can fire' : '';
  }

  function newBoard() { state.shots = []; state.lastShotAt = 0; state.fleetHits = 0; clearInterval(waitTimer); }

  function onClick(e) {
    const b = e.target.closest('[data-act]');
    if (!b || b.tagName === 'SELECT') return;
    const act = b.dataset.act;
    const target = currentTarget();
    if (act === 'cell') {
      // click a cell: untried → miss → hit → untried
      const i = Number(b.dataset.i), s = shotMap()[i];
      mark(i, !s ? 'miss' : s === 'miss' ? 'hit' : null);
      return;
    }
    if (act === 'hit' && target >= 0) { mark(target, 'hit'); return; }
    if (act === 'miss' && target >= 0) { mark(target, 'miss'); return; }
    if (act === 'copy') { K.copyText(currentAnswer(), b, '📋 Copy'); return; }
    if (act === 'undo') state.shots = state.shots.slice(0, -1);
    else if (act === 'newboard') newBoard();
    else if (act === 'clear') { newBoard(); state.fleet = []; $('battleshipText').value = ''; }
    else if (act === 'sample') { newBoard(); $('battleshipText').value = SAMPLE_MANUAL; handleText(SAMPLE_MANUAL); return; }
    else if (act === 'status') { const k = Number(b.dataset.k); state.fleet = state.fleet.map((s, j) => (j === k ? { ...s, status: STATUS_NEXT[s.status] ?? 'afloat' } : s)); }
    else if (act === 'ship-x') { const k = Number(b.dataset.k); state.fleet = state.fleet.filter((_, j) => j !== k); }
    else return;
    update();
  }

  function onChange(e) {
    if (e.target.dataset.act !== 'add-ship' || !e.target.value) return;
    state.fleet = [...state.fleet, { len: Number(e.target.value), status: null }];
    update();
  }

  function analyze() {
    const hits = hitCount();
    // "afloat" in the list is only trusted while no hit has come in since it was pasted
    const trustAfloat = state.fleet.some(s => s.status) && hits === state.fleetHits;
    state.res = analyzeBattleship({ cols: COLS, rows: ROWS, ships: state.fleet, shots: shotMap(), trustAfloat });
    state.trustAfloat = trustAfloat;
    return state.res;
  }
  function currentTarget() {
    const res = state.res;
    return res && res.ok && !res.done && res.best.length ? res.best[0] : -1;
  }
  function currentAnswer() {
    const res = state.res, t = currentTarget();
    return res && res.done ? '' : t >= 0 ? `Fire ${cellName(t, COLS)}` : '';
  }

  function update() {
    if (!$('battleshipAnswer')) return;
    const res = analyze();
    const map = shotMap();
    const hits = hitCount();
    const target = currentTarget();
    const targetName = target >= 0 ? cellName(target, COLS) : '';
    const fleetCells = state.fleet.reduce((a, s) => a + s.len, 0);

    $('battleshipFleet').innerHTML = state.fleet.map((s, k) => `
      <span class="bs-ship ${s.status || 'unknown'}">
        <button type="button" data-act="status" data-k="${k}" title="Click: afloat → sunk → unknown">${'▮'.repeat(s.len)} ${s.len}-cell · ${s.status || '?'}</button>
        <button type="button" class="mk-x" data-act="ship-x" data-k="${k}" title="Remove">✕</button>
      </span>`).join('') + `
      <select class="mk-select" data-act="add-ship" title="Add a ship"><option value="">+ ship</option>${[1, 2, 3, 4, 5, 6].map(n => `<option value="${n}">${n}-cell</option>`).join('')}</select>`;
    $('battleshipFleetNote').innerHTML = state.fleet.some(s => s.status === 'afloat') && !state.trustAfloat && hits > 0
      ? '<div class="mk-dim">Hit marked: if a ship sank, paste the new fleet list or click its chip to mark it sunk.</div>' : '';

    $('battleshipAnswer').innerHTML = res.done ? 'ALL SHIPS SUNK'
      : targetName ? `FIRE ${esc(targetName)}`
      : `<span class="ph">${esc(!state.fleet.length ? 'PASTE THE MANUAL TEXT (THE ENEMY FLEET)' : res.ok ? '— — —' : res.reason.toUpperCase())}</span>`;
    $('battleshipStats').textContent = !res.ok ? 'Fleet + your hit / miss marks → best cell'
      : res.done ? `${state.shots.length} shots · done`
      : `${res.mode === 'target' ? 'Finish the hit ship' : 'Search'} · ${pct(res.bestP)}% hit chance · shot ${state.shots.length + 1}`;
    $('battleshipCopyBtn').disabled = !currentAnswer();

    $('battleshipReport').innerHTML = res.ok && !res.done && target >= 0 ? `
      <div class="bs-report">
        <span>${esc(targetName)} was a</span>
        <button type="button" class="mk-btn hit" data-act="hit">💥 HIT</button>
        <button type="button" class="mk-btn miss" data-act="miss">🌊 MISS</button>
        <span id="battleshipWait" class="bs-wait"></span>
      </div>` : '';
    showWait();

    const ties = res.ties.filter(i => i !== target).map(i => cellName(i, COLS));
    $('battleshipTies').innerHTML = ties.length && !res.done
      ? `<div class="mk-note">Just as good: <b>${esc(ties.join(', '))}</b> — a shot knocks that slot's module offline for 20 s, so pick one whose module isn't being worked on.</div>` : '';

    if (!state.fleet.length) { $('battleshipBoard').innerHTML = ''; $('battleshipNote').innerHTML = ''; }
    else {
      let g = '<span></span>';
      for (let c = 0; c < COLS; c++) g += `<span class="bs-lbl">${colLetter(c)}</span>`;
      for (let i = 0; i < COLS * ROWS; i++) {
        if (i % COLS === 0) g += `<span class="bs-lbl">${Math.floor(i / COLS) + 1}</span>`;
        const s = map[i];
        const p = res.prob[i] || 0;
        const isTarget = i === target, isTie = res.ties.includes(i) && !isTarget;
        const sure = res.certain.includes(i);
        const heat = !s && !res.done ? Math.min(1, p / Math.max(0.01, res.bestP || 1)) : 0;
        const cls = `bs-cell ${s || 'open'} ${isTarget ? 'target' : ''} ${isTie ? 'tie' : ''} ${sure ? 'sure' : ''} ${!s && res.ok && p === 0 && !res.done ? 'empty' : ''}`;
        const style = !s ? ` style="background: rgba(255,216,117,${(heat * 0.32).toFixed(3)});"` : '';
        const label = s === 'hit' ? '✕' : s === 'miss' ? '•' : isTarget ? '🎯' : res.ok && !res.done ? pct(p) : '';
        g += `<button type="button" class="${cls}"${style} data-act="cell" data-i="${i}" title="${cellName(i, COLS)}: ${s || `${pct(p)}% chance of a ship`} — click: miss → hit → clear">${label}</button>`;
      }
      $('battleshipBoard').innerHTML = `<div class="bs-board">${g}</div>`;
      $('battleshipNote').innerHTML = `<div class="mk-dim">Click a cell to mark it: once = <b>miss</b> •, twice = <b>hit</b> ✕, three times = clear. Numbers are each cell's chance (%) of holding a ship. ${state.shots.length} shot${state.shots.length === 1 ? '' : 's'} · ${hits} hit${hits === 1 ? '' : 's'} of ${fleetCells} ship cells.</div>`;
    }

    $('battleshipWork').innerHTML = `
      <div>It counts every way the fleet (${esc(state.fleet.map(s => s.len).join(' + ') || '—')} cells) could still lie on the ${COLS}×${ROWS} board: straight, not overlapping, covering every hit and no miss${state.fleet.some(s => s.status === 'sunk') ? ', with each sunk ship lying wholly on hits' : ''}${state.trustAfloat ? ', and no afloat ship lying wholly on hits' : ''}.</div>
      ${res.ok && !res.done ? `<div>${res.exact ? `${res.total.toLocaleString()} layouts fit.` : 'Too many layouts to count one by one — each ship is counted on its own instead.'} A cell's number is the share of them with a ship there; the highest is fired at.</div>` : ''}
      <div>No hit yet → it spreads shots over the middle, where the most layouts pass. After a hit → it follows the line the ship can still lie on, until the list says it sank.</div>
      <div class="mk-dim">With a 3-cell and a 2-cell ship on 6×6, simulated games took about 15 shots on average (worst 25) — about 5 minutes at 20 s a shot.</div>`;
  }

  window.initBattleshipModule = function () {
    injectStyles();
    renderUI();
  };
})();
